#!/bin/bash
set -e
mkdir -p agents/config agents/regressions

echo '' | base64 -d > agents/README.md
echo '' | base64 -d > agents/agent2_economic.py
echo '' | base64 -d > agents/agent3_gossip.py
echo '' | base64 -d > agents/agent5_invariant.py
echo '' | base64 -d > agents/agent6_patch.py
echo '' | base64 -d > agents/config/devnet3.toml
echo '' | base64 -d > agents/config/devnet4.toml
echo '' | base64 -d > agents/devnet_guard.py
echo '' | base64 -d > agents/invariants.md
echo '' | base64 -d > agents/observability.py
echo '' | base64 -d > agents/regressions/test_regression_template.py
echo '' | base64 -d > agents/run_suite.py

echo "Done. Files installed:"
find agents -type f | sort